struct Node *copyRandomList(struct Node *head) {
  if (head == NULL) {
    return NULL;
  }

  struct Node *orig[1001];
  struct Node *copy[1001];
  int size = 0;

  for (struct Node *cur = head; cur != NULL; cur = cur->next) {
    struct Node *node = (struct Node *)malloc(sizeof(struct Node));
    node->val = cur->val;
    node->next = NULL;
    node->random = NULL;
    orig[size] = cur;
    copy[size] = node;
    size++;
  }

  for (int i = 0; i < size; i++) {
    for (int j = 0; j < size; j++) {
      if (orig[i]->next != NULL && orig[j] == orig[i]->next) {
        copy[i]->next = copy[j];
      }
      if (orig[i]->random != NULL && orig[j] == orig[i]->random) {
        copy[i]->random = copy[j];
      }
    }
  }

  return copy[0];
}

class Solution {
public:
  Node *copyRandomList(Node *head) {
    if (head == nullptr) {
      return nullptr;
    }
    unordered_map<Node *, Node *> mapping;
    for (Node *cur = head; cur != nullptr; cur = cur->next) {
      mapping[cur] = new Node(cur->val);
    }
    for (Node *cur = head; cur != nullptr; cur = cur->next) {
      mapping[cur]->next = cur->next != nullptr ? mapping[cur->next] : nullptr;
      mapping[cur]->random = cur->random != nullptr ? mapping[cur->random] : nullptr;
    }
    return mapping[head];
  }
};

func copyRandomList(head *Node) *Node {
	if head == nil {
		return nil
	}
	mapping := map[*Node]*Node{}
	for cur := head; cur != nil; cur = cur.Next {
		mapping[cur] = &Node{Val: cur.Val}
	}
	for cur := head; cur != nil; cur = cur.Next {
		mapping[cur].Next = mapping[cur.Next]
		mapping[cur].Random = mapping[cur.Random]
	}
	return mapping[head]
}

class Node {
  int val;
  Node next;
  Node random;

  public Node(int val) {
    this.val = val;
    this.next = null;
    this.random = null;
  }
}

class Solution {
  public Node copyRandomList(Node head) {
    if (head == null) {
      return null;
    }
    Map<Node, Node> mapping = new HashMap<Node, Node>();
    for (Node cur = head; cur != null; cur = cur.next) {
      mapping.put(cur, new Node(cur.val));
    }
    for (Node cur = head; cur != null; cur = cur.next) {
      mapping.get(cur).next = cur.next != null ? mapping.get(cur.next) : null;
      mapping.get(cur).random = cur.random != null ? mapping.get(cur.random) : null;
    }
    return mapping.get(head);
  }
}

class Solution:
    def copyRandomList(self, head: Optional["Node"]) -> Optional["Node"]:
        if head is None:
            return None

        mapping = {}
        cur = head
        while cur:
            mapping[cur] = Node(cur.val)
            cur = cur.next

        cur = head
        while cur:
            mapping[cur].next = mapping.get(cur.next)
            mapping[cur].random = mapping.get(cur.random)
            cur = cur.next

        return mapping[head]

impl Solution {
  pub fn copy_random_list(head: Option<Rc<RefCell<Node>>>) -> Option<Rc<RefCell<Node>>> {
    let head = head?;
    let mut mapping: HashMap<usize, Rc<RefCell<Node>>> = HashMap::new();

    let mut cur = Some(head.clone());
    while let Some(node) = cur {
      let key = Rc::as_ptr(&node) as usize;
      mapping.insert(key, Rc::new(RefCell::new(Node::new(node.borrow().val))));
      cur = node.borrow().next.clone();
    }

    let mut cur = Some(head.clone());
    while let Some(node) = cur {
      let key = Rc::as_ptr(&node) as usize;
      let (next_key, random_key) = {
        let node_ref = node.borrow();
        (
          node_ref.next.as_ref().map(|n| Rc::as_ptr(n) as usize),
          node_ref.random.as_ref().map(|n| Rc::as_ptr(n) as usize),
        )
      };
      let copy = mapping.get(&key).unwrap().clone();
      copy.borrow_mut().next = next_key.and_then(|k| mapping.get(&k).cloned());
      copy.borrow_mut().random = random_key.and_then(|k| mapping.get(&k).cloned());
      cur = node.borrow().next.clone();
    }

    mapping.get(&(Rc::as_ptr(&head) as usize)).cloned()
  }
}

const copyRandomList = (head: Node | null): Node | null => {
  if (head === null) return null;

  const mapping = new Map<Node, Node>();
  for (let cur: Node | null = head; cur; cur = cur.next) {
    mapping.set(cur, new Node(cur.val));
  }

  for (let cur: Node | null = head; cur; cur = cur.next) {
    const copy = mapping.get(cur)!;
    copy.next = cur.next ? mapping.get(cur.next)! : null;
    copy.random = cur.random ? mapping.get(cur.random)! : null;
  }

  return mapping.get(head)!;
};
